            int n = gx * gy;
            var b = new floatBSRBuilder(n, n, 1, 1, Allocator.Temp, 5 * n);
            for (int y = 0; y < gy; y++)
                for (int x = 0; x < gx; x++)
                {
                    int i = y * gx + x;
                    b.AddValue(i, i, (float)4);
                    if (x > 0) b.AddValue(i, i - 1, (float)(-1));
                    if (x < gx - 1) b.AddValue(i, i + 1, (float)(-1));
